      "level.H": "Cao",
      "level.M": "Trung bình",
      "level.L": "Thấp",
      "axis.score": "{axis} · Tỷ lệ phản hồi đúng {score}% · {level}",
      "name.allH": "Nhà thám hiểm tận dụng thế mạnh trong mọi lĩnh vực",
      "name.allM": "Người khám phá so sánh các chiến lược toàn diện",
      "name.allL": "Trình khám phá từng bước toàn diện",
      "summary.allL": "Tỷ lệ câu trả lời đúng trong bài tập này ở mức thấp ở cả bốn lĩnh vực. Những kết quả này không mô tả đầy đủ tiềm năng hoặc hiệu suất của bạn. Hãy bắt đầu bằng cách tìm cách giảm bớt gánh nặng của bạn và làm cho nó dễ hiểu và dễ dàng tiến hành.",
      "summary.allM": "Tỷ lệ câu trả lời đúng cho nhiệm vụ này nằm ở mức trung bình cho cả bốn lĩnh vực. Điều này không có nghĩa là chúng ta phản ứng linh hoạt với mọi nhiệm vụ. So sánh các phương pháp học tập hoặc bài tập thực tế mà bạn quan tâm.",
      "summary.allH": "Tỷ lệ câu trả lời đúng trong bài tập này nằm ở mức cao hơn trong cả bốn lĩnh vực. Hiệu suất cao trong các nhiệm vụ phức tạp không được đảm bảo. Hãy thử các phương pháp khác nhau đối với nhiệm vụ bạn quan tâm và xem chúng thực sự hoạt động như thế nào cũng như cảm thấy căng thẳng như thế nào.",
      "summary.mixed": "Hãy cùng nhau xem xét phạm vi câu trả lời đúng trong bốn lĩnh vực để điều chỉnh phương pháp học tập/làm việc và mức độ trợ giúp của bạn. Đừng xác định điểm mạnh của bạn chỉ dựa trên số điểm tương đối cao hoặc giới hạn lựa chọn nghề nghiệp của bạn ở mức điểm thấp.",
      "reason.tie": "Bốn điểm bằng nhau. So sánh các phương pháp khác nhau mà không quyết định một lĩnh vực nào là ưu việt hơn.",
      "interpret.separate": "Loại 81 là sự kết hợp giữa cao, trung bình và thấp ở từng khu vực, còn sự khác biệt về điểm số của 4 khu vực và so sánh xử lý đồng thời và xử lý tuần tự là những thông tin riêng biệt. Điểm giống nhau không có nghĩa là điểm số giống nhau hoặc tất cả các phương pháp đều được sử dụng tốt như nhau.",
      "interpret.processing": "So sánh xử lý đồng thời và tuần tự cho thấy sự khác biệt giữa hai điểm số. Dấu hiệu ưu việt không khẳng định tính hiệu quả hoặc đủ sức mạnh của phương pháp. Hãy thử sử dụng hình ảnh và biểu đồ từng bước cho các nhiệm vụ thực tế và so sánh độ chính xác của bạn với sự trợ giúp mà bạn cần.",
      "processing.balancedSupport": "Người học cân bằng · Hỗ trợ từng bước được đề xuất cho cả hai phương pháp xử lý",
      "evidence.template": "Chọn một hoạt động bạn thực sự đã thực hiện và ghi lại mục tiêu, phương pháp đã sử dụng, những lĩnh vực bạn cần trợ giúp và kết quả đã xác định. Đừng sử dụng những khả năng được ước tính từ điểm số hoặc thành tích mà bạn chưa từng trải qua như thể đó là trải nghiệm của chính bạn.",
      "evidence.verify": "Kiểm tra biểu thức 'điểm mạnh' bằng các ví dụ về hiệu suất thực tế. Tính cách, khả năng hợp tác và hiệu suất không chỉ được quyết định bởi kết quả.",
      "evidence.domain": "Lĩnh vực nhận thức",
      "evidence.method": "Thử cái gì",
      "evidence.observation": "Những gì cần kiểm tra trong thực tế",
      "faq.supportQuestion": "Tôi có thể sử dụng loại trợ giúp nào trước tiên khi cảm thấy nhiệm vụ khó khăn?",
